using System.Collections; using System.Collections.Generic; using UnityEngine;  using DG.Tweening; using UnityEngine.UI;  public class TarotPanelManager : MonoBehaviour {     [HideInInspector] public List<TarotCard> tarotCards;      public List<CardMoveArea> cardMoveAreas;     int selectingCount = 3;      public RectTransform cardsPivot;      public int cardsPivotDistance = 50;      public float rotateAmount = 10f;     public float dragSensivity = 0.03f;      public int bottomOffset = 200;      int direction;      float firtsCardAngleQuaternionZ;     float lastCardAngleQuaternionZ;      float firtsCardAngle;     float lastCardAngle;      Vector2 beginDragPos;     List<Vector2> lastDragPositions;      Quaternion beginCardPivotRotation;      List<Sprite> cardSprites;      [HideInInspector] public GameObject followingCard;     [HideInInspector] public GameObject followingCardTrigger;      bool canDrag;     bool userCanInput;      public float _speed;     float speed     {         get         {             return _speed;         }         set         {             if (value >= -maxSpeed && value <= maxSpeed)                 _speed = value;             else             {                 if (value < 0)                     _speed = -maxSpeed;                 else                     _speed = maxSpeed;             }         }     }          float speedDirection;     public float deceleration;     public float maxSpeed = 100f;      ChatManager chatManager;      bool isDestroyed;      private void Awake()     {         lastDragPositions = new List<Vector2>();          for (int i = 0; i < cardsPivot.childCount; i++)         {             tarotCards.Add(cardsPivot.GetChild(i).GetComponent<TarotCard>());         }          chatManager = FindObjectOfType<ChatManager>();     }      void Start()     {         if (chatManager.PlayerDataManager.GetChatVariableValue("tarot modu") != "tümü")         {             Destroy(cardMoveAreas[0].rectTransform.gameObject);             Destroy(cardMoveAreas[2].rectTransform.gameObject);             cardMoveAreas.RemoveAt(2);             cardMoveAreas.RemoveAt(0);              selectingCount = 1;              if (chatManager.PlayerDataManager.GetChatVariableValue("tarot modu") == "geçmiş")             {                 cardMoveAreas[0].text.text = "Geçmiş";                 cardMoveAreas[0].cardIndex = 0;             }             else if (chatManager.PlayerDataManager.GetChatVariableValue("tarot modu") == "şimdi")             {                 cardMoveAreas[0].text.text = "Şimdi";                 cardMoveAreas[0].cardIndex = 0;             }             else if (chatManager.PlayerDataManager.GetChatVariableValue("tarot modu") == "gelecek")             {                 cardMoveAreas[0].text.text = "Gelecek";                 cardMoveAreas[0].cardIndex = 0;             }             else             {                 cardMoveAreas[0].text.text = " ";                 cardMoveAreas[0].cardIndex = 0;             }         }          cardSprites = new List<Sprite>();         foreach(Sohbet sohbet in chatManager.tarotSohbetleri)         {             cardSprites.Add(sohbet.contentImage.image);         }          foreach(CardMoveArea cardMoveArea in cardMoveAreas)         {             cardMoveArea.effect.Initiliaze();         }          OpenPanel();     }       void Update()     {         if (speedDirection == 1)         {             if (speed > 0)             {                 speed -= Time.deltaTime * deceleration;                 SetCardsPivotRotationWithSpeed();             }         }         else         {             if (speed < 0)             {                 speed += Time.deltaTime * deceleration;                 SetCardsPivotRotationWithSpeed();             }         }          if (canDrag)         {             AddElementInLastDragPosList(Input.mousePosition);         }          if (!isDestroyed)         {             if (selectingCount <= 0)             {                 isDestroyed = true;                 StartCoroutine(ClosePanelWithDelay("tarot oku"));             }             else             {                 if (!chatManager.tarotSettings.IsTarotCardPickerMod(chatManager.PlayerDataManager.GetChatVariableValue("mod")))                 {                     chatManager.tarotSohbetleri = new List<Sohbet>();                     StartCoroutine(ClosePanelWithDelay());                 }             }         }     }      IEnumerator ClosePanelWithDelay(string mod)     {         int index = 0;         float delay = 8.5f;          for (int i = tarotCards.Count - 1; i >= 0; i--)         {             if (tarotCards[i].rectTransform.childCount > 0)             {                 tarotCards[i].EndAnimation(index);                 index += 1;             }         }          foreach(CardMoveArea cardMoveArea in cardMoveAreas)         {             Color.RGBToHSV(cardMoveArea.cardImage.color, out float h, out float s, out float v);             cardMoveArea.cardImage.DOColor(Color.HSVToRGB(h, s, v - 3f * v / 5f), 0.75f);              float loadTime = Random.Range(2.5f, delay);             StartCoroutine(ChangeTartgetSpriteWithDelay(cardMoveArea.loadginCircleRect.GetComponent<Image>(), cardMoveArea.loadedSprite, loadTime));             cardMoveArea.loadginCircleRect.gameObject.SetActive(true);             cardMoveArea.loadginCircleRect.DORotate(new Vector3(0, 0, 360f * Random.Range(1.5f, 5f)), loadTime, RotateMode.FastBeyond360);             cardMoveArea.loadginCircleRect.SetAsLastSibling();         }          yield return new WaitForSeconds(delay);         chatManager.ClickVirtualButton(mod);         Destroy(gameObject);     }      IEnumerator ChangeTartgetSpriteWithDelay(Image image, Sprite sprite, float delay)     {         yield return new WaitForSeconds(delay);         image.GetComponent<RectTransform>().rotation = new Quaternion();         image.GetComponent<RectTransform>().DOScale(0f, 0.2f);         image.DOFade(0f, 0.2f);         yield return new WaitForSeconds(0.2f);         image.sprite = sprite;         image.GetComponent<RectTransform>().DOScale(1f, 0.2f);         image.DOFade(1f, 0.2f);     }      IEnumerator ClosePanelWithDelay()     {         isDestroyed = true;         yield return new WaitForSeconds(1f);         Destroy(gameObject);     }      IEnumerator SetCardsFirstRotation()     {         yield return new WaitForEndOfFrame();         float amount = firtsCardAngleQuaternionZ;          cardsPivot.rotation = Quaternion.Euler(0, 0, Mathf.Clamp( amount, lastCardAngleQuaternionZ, firtsCardAngleQuaternionZ));         Debug.Log(new Quaternion(0, 0, Mathf.Clamp(amount, lastCardAngleQuaternionZ, firtsCardAngleQuaternionZ), cardsPivot.rotation.w).eulerAngles.z);         SetActiveCardsImages(amount);          foreach(TarotCard tarotCard in tarotCards)         {             tarotCard.StartAnimation();         }          //Cardlarin ekrana gelis animasyonu 0.5f saniye surmekte. O sureden biraz daha fazlasi boyunca kullanicinin ekrana input vermesinin onune gecilmistir.         //Degerler simdilik hard code olarak birakildi.         yield return new WaitForSeconds(0.6f);         userCanInput = true;     }      IEnumerator MoveAreasStartAnimation()     {         Vector3 firstScale = new Vector3();         foreach (CardMoveArea cardMoveArea in cardMoveAreas)         {             firstScale = cardMoveArea.rectTransform.localScale;             cardMoveArea.rectTransform.localScale = Vector3.zero;         }                  yield return new WaitForSeconds(0.5f);                  foreach (CardMoveArea cardMoveArea in cardMoveAreas)         {             cardMoveArea.rectTransform.DOScale(firstScale, 0.5f);         }     }      public void OpenPanel()     {         userCanInput = false;          gameObject.SetActive(true);         SetCardPositions();         StartCoroutine(SetCardsFirstRotation());         StartCoroutine(MoveAreasStartAnimation());     }      void SetCardPositions()     {         cardsPivot.anchoredPosition = new Vector2(0, 0 - cardsPivotDistance + tarotCards[0].rectTransform.rect.height / 2f + bottomOffset);         cardsPivot.rotation = new Quaternion();         for (int i = 0; i < tarotCards.Count; i++)         {             if (tarotCards[i].rectTransform != null)                 tarotCards[i].rectTransform.localPosition = new Vector3(tarotCards[i].rectTransform.localPosition.x, cardsPivotDistance, tarotCards[i].rectTransform.localPosition.z);             tarotCards[i].pivotRectTransform.rotation = new Quaternion();             tarotCards[i].pivotRectTransform.Rotate(0, 0, (rotateAmount / (tarotCards.Count / 2f)) * (tarotCards.Count / 2f - i));         }          firtsCardAngleQuaternionZ = -tarotCards[tarotCards.Count - 1].pivotRectTransform.eulerAngles.z;         lastCardAngleQuaternionZ = -tarotCards[0].pivotRectTransform.eulerAngles.z;          if (firtsCardAngleQuaternionZ > 180)             firtsCardAngleQuaternionZ -= 360;         else if (firtsCardAngleQuaternionZ < -180)             firtsCardAngleQuaternionZ += 360;          if (lastCardAngleQuaternionZ > 180)             lastCardAngleQuaternionZ -= 360;         else if (lastCardAngleQuaternionZ < -180)             lastCardAngleQuaternionZ += 360;          firtsCardAngle = -tarotCards[tarotCards.Count - 1].pivotRectTransform.rotation.z;         lastCardAngle = -tarotCards[0].pivotRectTransform.rotation.z;     }      void AddElementInLastDragPosList(Vector2 value)     {         while (lastDragPositions.Count >= 5)         {             lastDragPositions.RemoveAt(0);         }          lastDragPositions.Add(value);     }      Vector2 GetAvarageLastDragPositionValue()     {         Vector2 totalValue = new Vector2();         foreach (Vector2 value in lastDragPositions)         {             totalValue += value;         }          return totalValue / ((float)lastDragPositions.Count);     }      void SetCardsPivotRotation()     {         float amount = (beginDragPos.x - Input.mousePosition.x) * (dragSensivity / 100f);          cardsPivot.rotation = new Quaternion(0, 0, Mathf.Clamp(beginCardPivotRotation.z + amount, lastCardAngle, firtsCardAngle), cardsPivot.rotation.w);          SetActiveCardsImages(amount);          //asagidaki kod artik update icinde calisiyor         //AddElementInLastDragPosList(Input.mousePosition);     }      void SetCardsPivotRotationWithSpeed()     {         float amount = speed/100f;          if (cardsPivot.rotation.z > lastCardAngle && cardsPivot.rotation.z < firtsCardAngle)             cardsPivot.Rotate(new Vector3(0, 0, amount));         else         {             speed = 0;         }          //Eger olur da yukaridaki ayarlamanin sonunda sinirin disina cikarsa diye yapilir. Cunku eger cardsPivot.rotation.eulerAngles.z-lastCardAngle'dan buyuk bir deger eklenirse siniri asar ve ilk basta yukaridaki durumu da saglamis olur.         cardsPivot.rotation = new Quaternion(0, 0, Mathf.Clamp(cardsPivot.rotation.z, lastCardAngle, firtsCardAngle), cardsPivot.rotation.w);          SetActiveCardsImages(amount);     }      public void OnDragCard(GameObject followingCard)     {         if (followingCardDestroyDelay == null && canDrag && userCanInput)         {             if (direction == 0)             {                 if (Mathf.Abs(Input.mousePosition.x - beginDragPos.x) >= Mathf.Abs(Input.mousePosition.y - beginDragPos.y))                 {                     direction = 1;                  }                 else                 {                     direction = -1;                 }             }             else if (direction == 1)             {                 SetCardsPivotRotation();             }             else if (direction == -1)             {                 if (this.followingCard == null)                 {                     TarotCard tarotCard = followingCard.GetComponent<RectTransform>().parent.GetComponent<RectTransform>().parent.GetComponent<TarotCard>();                     if (tarotCard != null)                     {                         if (!tarotCard.isUsed)                         {                             CreateFollowCard(followingCard);                         }                     }                 }                 else                 {                     SetFollowingCardPosition();                 }             }             else             {                 direction = 0;             }         }     }      public void OnDragMain()     {         if (followingCardDestroyDelay == null && canDrag && userCanInput)         {             SetCardsPivotRotation();             //Son mouse pozisyonlarinin kaydedilmesi icin direction 1 yani horizontal olmalidir. Bu kontrol endDragta yapiliri. Onun disinda drag boyunca direction 1e esitlemek mainDrag icinde kullanilmaz.             direction = 1;         }     }      void CreateFollowCard(GameObject followingCard)     {         this.followingCard = Instantiate(followingCard, followingCard.GetComponent<RectTransform>().parent.GetComponent<RectTransform>());         this.followingCard.GetComponent<RectTransform>().position = followingCard.GetComponent<RectTransform>().position;          followingCardTrigger = followingCard;          //Kart kapatilir ama isUsed ayarlanmaz. Eger kart secilirse ve yerine yerlesirse ayarlanir.         followingCard.GetComponent<Image>().color = new Color(followingCard.GetComponent<Image>().color.r, followingCard.GetComponent<Image>().color.g, followingCard.GetComponent<Image>().color.b, 0);     }      void SetFollowingCardPosition()     {         if (followingCard != null)         {             followingCard.GetComponent<RectTransform>().position = Input.mousePosition;         }     }      public void OnBeginDrag()     {         if (followingCardDestroyDelay == null)         {             if (followingCard != null)             {                 followingCardTrigger.GetComponent<Image>().color = new Color(followingCardTrigger.GetComponent<Image>().color.r, followingCardTrigger.GetComponent<Image>().color.g, followingCardTrigger.GetComponent<Image>().color.b, 1);                 Destroy(followingCard);                 followingCard = null;                 followingCardTrigger = null;                 StopCoroutine(followingCardDestroyDelay);             }              direction = -2;             beginDragPos = Input.mousePosition;             beginCardPivotRotation = cardsPivot.rotation;              canDrag = true;             //asagidaki kod artik update icinde calisiyor             //AddElementInLastDragPosList(Input.mousePosition);             speed = 0;             lastDragPositions = new List<Vector2>();         }     }      public void OnEndDrag()     {         if (followingCardDestroyDelay == null)         {             if (followingCard != null)             {                  RectTransform followingCardRt = followingCard.GetComponent<RectTransform>();                 RectTransform followingCardTriggerRt = followingCardTrigger.GetComponent<RectTransform>();                 CardMoveArea selectedMoveArea = new CardMoveArea(followingCardTriggerRt);                  float distance = Vector2.Distance(followingCardRt.position, selectedMoveArea.rectTransform.position);                  foreach (CardMoveArea cardMoveArea in cardMoveAreas)                 {                     float currentDistance = Vector2.Distance(followingCardRt.position, cardMoveArea.rectTransform.position);                     if (!cardMoveArea.isUsed)                     {                         if (distance < 0)                         {                             distance = currentDistance;                             selectedMoveArea = cardMoveArea;                         }                         else if (distance > currentDistance)                         {                             distance = currentDistance;                             selectedMoveArea = cardMoveArea;                         }                     }                      Debug.Log(cardMoveArea.rectTransform.gameObject.name + ": " + currentDistance);                 }                  followingCardRt.DOMove(selectedMoveArea.rectTransform.position, 0.5f);                 followingCardRt.DORotateQuaternion(selectedMoveArea.rectTransform.rotation, 0.5f);                 followingCardDestroyDelay = FollowingCardDestroyDelay(0.5f, selectedMoveArea);                 StartCoroutine(followingCardDestroyDelay);             }         }          canDrag = false;          if (direction == 1)         {             //Speed ayarlari 2340x1080 cozunurlukte denendigi icin 1080 degeri hard code olarak birakildi.             speed = (GetAvarageLastDragPositionValue().x - Input.mousePosition.x) * (Screen.width / 1080f);             Debug.Log(Screen.width);             Debug.Log(Input.mousePosition);              if (speed > 0)                 speedDirection = 1;             else                 speedDirection = -1;         }     }      public IEnumerator followingCardDestroyDelay;     IEnumerator FollowingCardDestroyDelay(float delay, CardMoveArea selectedMoveArea)     {         yield return new WaitForSeconds(delay);         if (followingCard != null)         {             if (selectedMoveArea.rectTransform.gameObject == followingCardTrigger)             {                 Image cardImage = followingCardTrigger.GetComponent<Image>();                 cardImage.color = new Color(cardImage.color.r, cardImage.color.g, cardImage.color.b, 1);                 Destroy(followingCard.gameObject);                 followingCard = null;                 followingCardTrigger = null;             }             else             {                 TarotCard tarotCard = followingCardTrigger.GetComponent<RectTransform>().parent.GetComponent<RectTransform>().parent.GetComponent<TarotCard>();                 Image cardImage = followingCardTrigger.GetComponent<Image>();                 followingCardTrigger.gameObject.SetActive(false);                 cardImage.color = new Color(cardImage.color.r, cardImage.color.g, cardImage.color.b, 1);                 tarotCard.isUsed = true;                 selectedMoveArea.isUsed = true;                 selectedMoveArea.cardImage = followingCard.GetComponent<Image>();                  RectTransform followingCardRt = followingCard.GetComponent<RectTransform>();                 followingCardRt.SetParent(selectedMoveArea.rectTransform);                 followingCardRt.DORotate(new Vector3(0, 90, 0), 0.25f);                 selectedMoveArea.effect.rectTransform.SetAsLastSibling();                 StartCoroutine(selectedMoveArea.effect.FadeOut());                  Vector2 followingCardFirsScale = followingCardRt.localScale;                 followingCardRt.DOScale(new Vector3(followingCardFirsScale.x * 0.95f, followingCardFirsScale.y * 0.95f),0.25f);                  yield return new WaitForSeconds(0.25f);                 chatManager.ClickVirtualButton(chatManager.tarotSohbetleri[selectedMoveArea.cardIndex].gerekliDegiskenler[0].degiskenDegeri + " tepki");                 Debug.Log(chatManager.tarotSohbetleri[selectedMoveArea.cardIndex].gerekliDegiskenler[0].degiskenDegeri + " tepki");                 followingCardRt.GetComponent<Image>().sprite = cardSprites[selectedMoveArea.cardIndex];                 followingCardRt.DORotate(new Vector3(0, 0, 0), 0.25f);                 followingCardRt.DOScale(new Vector3(followingCardFirsScale.x * 0.85f, followingCardFirsScale.y * 0.85f), 0.25f);                  followingCard = null;                 followingCardTrigger = null;                  selectingCount -= 1;             }         }          followingCardDestroyDelay = null;     }      void SetActiveCardsImages(float direction)     {         for (int i = 0; i < tarotCards.Count; i++)         {             if (tarotCards[i].rectTransform.childCount == 0)             {                 if (tarotCards[i].rectTransform.position.x < Screen.width + 200 && tarotCards[i].rectTransform.position.x > 0 - 200)                 {                     if (direction < 0)                     {                         for (int u = tarotCards.Count - 1; u >= 0; u--)                         {                                                 if (tarotCards[u].rectTransform.position.x > Screen.width + 200 || tarotCards[u].rectTransform.position.x < 0 - 200)                             {                                 if (tarotCards[u].rectTransform.childCount > 0)                                 {                                     tarotCards[u].rectTransform.GetChild(0).SetParent(tarotCards[i].rectTransform);                                     tarotCards[i].rectTransform.GetChild(0).localPosition = new Vector3(0, 0, 0);                                     tarotCards[i].rectTransform.GetChild(0).localRotation = Quaternion.Euler(0, 0, 0);                                     if (tarotCards[i].isUsed)                                         tarotCards[i].rectTransform.GetChild(0).gameObject.SetActive(false);                                     else                                         tarotCards[i].rectTransform.GetChild(0).gameObject.SetActive(true);                                      break;                                 }                             }                          }                     }                     else                     {                         for (int u = 0; u < tarotCards.Count; u++)                         {                              if (tarotCards[u].rectTransform.position.x > Screen.width + 200 || tarotCards[u].rectTransform.position.x < 0 - 200)                             {                                 if (tarotCards[u].rectTransform.childCount > 0)                                 {                                     tarotCards[u].rectTransform.GetChild(0).SetParent(tarotCards[i].rectTransform);                                     tarotCards[i].rectTransform.GetChild(0).localPosition = new Vector3(0, 0, 0);                                     tarotCards[i].rectTransform.GetChild(0).localRotation = Quaternion.Euler(0, 0, 0);                                     if (tarotCards[i].isUsed)                                         tarotCards[i].rectTransform.GetChild(0).gameObject.SetActive(false);                                     else                                         tarotCards[i].rectTransform.GetChild(0).gameObject.SetActive(true);                                      break;                                 }                             }                          }                     }                 }             }         }     }      [System.Serializable]     public class CardMoveArea     {         public RectTransform rectTransform;         public RectTransform loadginCircleRect;         public Sprite loadedSprite;         public EffectLineFolder effect;         public Text text;         public int cardIndex;          [HideInInspector] public Image cardImage;         [HideInInspector] public bool isUsed;          public CardMoveArea(RectTransform rectTransform)         {             this.rectTransform = rectTransform;             loadginCircleRect = null;             cardImage = null;             isUsed = false;             text = null;             cardIndex = 0;         }          [System.Serializable]         public class EffectLineFolder         {             public RectTransform rectTransform;             [HideInInspector] public List<EffectLine> effectLines;             public Sprite unSelectedSprite, selectedSprite;              public EffectLineFolder(RectTransform folderRt)             {                 rectTransform = folderRt;                 Initiliaze();             }              public void Initiliaze()             {                 effectLines = new List<EffectLine>();                 for (int i = 0; i < rectTransform.childCount; i++)                 {                     effectLines.Add(new EffectLine(rectTransform.GetChild(i).GetComponent<RectTransform>(), unSelectedSprite));                 }             }              public IEnumerator FadeOut()             {                 foreach(EffectLine effectLine in effectLines)                 {                     effectLine.image.DOFade(0.2f, 0.4f);                 }                  yield return new WaitForSeconds(0.4f);                  foreach (EffectLine effectLine in effectLines)                 {                     effectLine.image.DOFade(1, 0.4f);                     effectLine.image.sprite = selectedSprite;                 }             }              [System.Serializable]             public class EffectLine             {                 [HideInInspector] public RectTransform rectTransform;                 [HideInInspector] public Image image;                  public EffectLine(RectTransform rt, Sprite sprite)                 {                     rectTransform = rt;                     image = rectTransform.GetComponent<Image>();                     image.sprite = sprite;                 }             }          }     } } 